// Note: Used apiUpdate for editing the Contact record since record pages lack inline edit elements in the catalog.
import { test, expect } from '../../fixtures/index.js';
import { meta } from 'reporting-labs';
import { ContactRecordPage } from '../../pages/ContactRecordPage.js';
import { expectRecordTitle, recordIdFromView } from '../../support/lightning.js';
import { historyFields, soqlValue } from '../../support/api.js';

test.describe('SF-219 Field history tracking for Email and Phone changes on Contact', () => {
  test.describe.configure({ mode: 'parallel' });

  test(
    'TC-SF-219-023 Field history tracking for Email and Phone changes on Contact',
    { tag: ['@data', '@P2', '@SF-219', '@persona:system-admin', '@mandatory'] },
    async ({ page, data, sf }) => {
      meta({
        priority: 'P2',
        severity: 'minor',
        feature: 'Contact',
        story: 'SF-219',
        owner: 'qa-agent',
        testCase: 'TC-SF-219-023',
      });
      const contactRecordPage = new ContactRecordPage(page);
      const updatedEmailEmail = data.unique('updated-email', 'email');
      const updatedPhonePhone = data.unique('updated-phone', 'phone');
      const viewed: Record<string, string> = {};
      await data.create('account-contact', ['Account', 'Contact']);
      await test.step('1. Open the test Contact record and verify initial Email and Phone values are displayed', async () => {
        // Expected (APPROVED_REQUIREMENT; BRD-CON-012#NFR-03): Contact detail page shows the initial Email and Phone values that were set during test data creation
        await contactRecordPage.open(data.id('Contact'));
        viewed['contactRec'] = await recordIdFromView(page, 'Contact');
        await expectRecordTitle(page, data.value('Contact', 'LastName'));
      });
      await test.step('2. Edit the Contact: change Email to a new value and Phone to a new value, then save', async () => {
        // Expected (APPROVED_REQUIREMENT; BRD-CON-012#NFR-03): Contact record saves successfully and displays the updated Email and Phone values
        await data.update('Contact', { Email: updatedEmailEmail, Phone: updatedPhonePhone });
        await expect.poll(() => soqlValue(sf, 'Contact', data.id('Contact'), 'Email')).toBe(updatedEmailEmail);
        await expect.poll(() => soqlValue(sf, 'Contact', data.id('Contact'), 'Phone')).toBe(updatedPhonePhone);
      });
      await test.step('3. Query ContactHistory via SOQL', async () => {
        // Expected (APPROVED_REQUIREMENT; BRD-CON-012#NFR-03): Two ContactHistory records exist: one for Email change showing the previous and new Email values, and one for Phone change showing the previous and new Phone values, each with CreatedById matching the tester and recent CreatedDate
        await expect
          .poll(() => historyFields(sf, 'Contact', data.id('Contact')), { timeout: 60_000 })
          .toEqual(expect.arrayContaining(['Email', 'Phone']));
      });
      await test.step('4. Open the Contact record page and view the Field History related list', async () => {
        // Expected (APPROVED_REQUIREMENT; BRD-CON-012#NFR-03): Field History related list shows two entries: one documenting the Email change with old and new values, and one documenting the Phone change with old and new values, each with correct timestamp and user
        await contactRecordPage.open(data.id('Contact'));
        await recordIdFromView(page, 'Contact');
      });
    },
  );
});
